(function(){"use strict";var selector=".featured-reading[data-reading-url],.card-reading[data-reading-url]";var wordRate=185;var maxParallel=2;var active=0,queue=[],started=new WeakSet(),requestCache=new Map();var viewportObserver=null,containerObserver=null,pendingScan=false;function readFromArticle(url){if(requestCache.has(url))return requestCache.get(url);var task=fetch(url,{credentials:"same-origin",cache:"default",redirect:"follow",priority:"low"}).then(function(response){if(!response.ok)throw new Error("HTTP "+response.status);return response.text();}).then(function(html){var doc=new DOMParser().parseFromString(html,"text/html");var body=doc.querySelector(".post-body");if(!body)throw new Error("Konten artikel tidak ditemukan");var articleText=body.textContent||body.innerText||"";var matches=articleText.trim().match(/\S+/g);var count=matches?matches.length:0;return Math.max(1,Math.ceil(count/wordRate))+" min read";});requestCache.set(url,task);return task;}function pump(){while(active<maxParallel&&queue.length){var item=queue.shift();active++;(function(el,url){readFromArticle(url).then(function(reading){if(!el.isConnected)return;var target=el.querySelector(".reading-time-value");if(!target)return;target.textContent=reading;el.classList.remove("reading-pending");}).catch(function(){el.classList.add("reading-unavailable");}).then(function(){active--;pump();});})(item.el,item.url);}}function queueNode(el){if(started.has(el))return;started.add(el);if(viewportObserver)viewportObserver.unobserve(el);try{var url=new URL(el.getAttribute("data-reading-url")||"",window.location.href);if(url.origin!==window.location.origin||!/^https?:$/.test(url.protocol))return;queue.push({el:el,url:url.href});pump();}catch(error){}}function scan(){document.querySelectorAll(selector).forEach(function(el){if(started.has(el)||el.hasAttribute("data-reading-watched"))return;el.setAttribute("data-reading-watched","1");if(viewportObserver)viewportObserver.observe(el);else queueNode(el);});}function scheduleScan(){if(pendingScan)return;pendingScan=true;requestAnimationFrame(function(){pendingScan=false;scan();});}function start(){if("IntersectionObserver"in window){viewportObserver=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting)queueNode(entry.target);});},{rootMargin:"550px 0px",threshold:0});}scan();var container=document.querySelector(".outer-wrapper");if(container&&"MutationObserver"in window){containerObserver=new MutationObserver(function(changes){if(changes.some(function(change){return change.addedNodes.length>0;}))scheduleScan();});containerObserver.observe(container,{childList:true,subtree:true});}}if(document.readyState==="complete")start();else window.addEventListener("load",start,{once:true});})();
